const deeperTopics = [{"grade": 6, "subject": "math", "name": "Длина окружности и площадь круга", "kind": "circle", "intro": "Окружность — граница круга. Длина границы и площадь внутри измеряются по-разному. Радиус связывает обе величины с числом π.", "rules": ["d = 2r; C = 2πr.", "Площадь круга S = πr².", "Если радиус увеличить в k раз, длина увеличится в k раз, площадь — в k² раз."], "problems": [["Длина границы", "Радиус 4 см. Найди длину окружности, принимая π = 3,14.", 25.12, "Подставь радиус в C = 2πr.", ["C = 2 × 3,14 × 4.", "Длина равна 25,12 см."]], ["Площадь кольца", "Радиусы двух концентрических окружностей 5 и 3 см. Найди площадь кольца, разделённую на π.", 16, "Вычти площади кругов.", ["S = π × 25 − π × 9 = 16π.", "Значит S/π = 16."]], ["Новый круг", "Радиус увеличили на 50%. На сколько процентов выросла площадь круга?", 125, "Коэффициент площади — квадрат коэффициента радиуса.", ["Новый радиус равен 1,5 старого.", "Площадь стала в 1,5² = 2,25 раза больше.", "Прирост: (2,25 − 1) × 100% = 125%."]]], "check": "Диаметр равен 10. Чему равен радиус?", "answer": 5}, {"grade": 6, "subject": "math", "name": "Объём и развёртки", "kind": "box", "intro": "Объём показывает вместимость тела, а развёртка — его поверхность на плоскости. Представляй параллелепипед как слои единичных кубиков.", "rules": ["V = abc для прямоугольного параллелепипеда.", "У куба V = a³ и S поверхности = 6a².", "1 литр = 1 дм³ = 1000 см³."], "problems": [["Объём коробки", "Размеры коробки 3, 4 и 5 см. Найди объём в см³.", 60, "Умножь три измерения.", ["В слое 3 × 4 = 12 кубиков.", "Пять слоёв дают 12 × 5 = 60 см³."]], ["Вместимость", "Аквариум имеет внутренние размеры 40 × 25 × 30 см. Сколько литров он вмещает?", 30, "Переведи кубические сантиметры в литры.", ["Объём 40 × 25 × 30 = 30000 см³.", "30000 : 1000 = 30 литров."]], ["Раскрашенные рёбра", "Куб 5 × 5 × 5 покрасили снаружи и разрезали на единичные кубики. Сколько имеют ровно две окрашенные грани?", 36, "Это кубики на рёбрах, кроме вершин.", ["У куба 12 рёбер.", "На каждом 5 − 2 = 3 нужных кубика.", "Всего 12 × 3 = 36."]]], "check": "Ребро куба 2. Найди объём.", "answer": 8}, {"grade": 7, "subject": "geometry", "name": "Углы и параллельные прямые", "kind": "parallel", "intro": "Секущая пересекает две прямые и образует пары углов. Равенство накрест лежащих углов позволяет доказать параллельность; при параллельных прямых это же равенство помогает вычислять углы.", "rules": ["Вертикальные углы равны; смежные дают 180°.", "При параллельных прямых накрест лежащие и соответственные углы равны.", "Односторонние внутренние углы в сумме дают 180°."], "problems": [["Смежный угол", "Один из смежных углов равен 63°. Найди второй.", 117, "Сумма смежных углов 180°.", ["Второй угол равен 180° − 63° = 117°."]], ["Односторонние углы", "Две параллельные прямые пересечены секущей. Односторонние внутренние углы относятся как 2 : 3. Найди меньший.", 72, "Всего пять равных частей в 180°.", ["Пусть углы 2x и 3x.", "5x = 180°, x = 36°.", "Меньший угол 72°."]], ["Две биссектрисы", "Провели биссектрисы двух смежных углов. Найди меньший угол между этими биссектрисами.", 90, "Пополам делятся оба угла, в сумме составляющие 180°.", ["Пусть смежные углы α и 180° − α.", "Между биссектрисами α/2 + (180° − α)/2 = 90°."]]], "check": "Вертикальный угол к углу 48° равен…", "answer": 48}, {"grade": 7, "subject": "geometry", "name": "Признаки равенства треугольников", "kind": "triangle", "intro": "Равные треугольники совпадают при наложении. Доказывать равенство можно по трём достаточным наборам элементов; соответствие вершин обязательно нужно сохранять.", "rules": ["Две стороны и угол между ними.", "Сторона и два прилежащих угла.", "Три стороны. Равенства только углов недостаточно."], "problems": [["Соответствующая сторона", "Треугольники ABC и DEF равны, A соответствует D, B — E, C — F. AB = 8. Найди DE.", 8, "Первые две соответствующие вершины задают равные стороны.", ["AB соответствует DE.", "Из равенства треугольников DE = 8."]], ["Общая сторона", "AB = AD = 5, BC = DC = 7. Треугольники ABC и ADC имеют общую сторону AC. Угол ABC = 110°. Найди ADC.", 110, "Используй три пары равных сторон.", ["AB = AD, BC = DC, AC — общая.", "Треугольники равны по трём сторонам.", "Соответствующие углы ABC и ADC равны 110°."]], ["Медиана", "В равнобедренном ABC стороны AB и AC равны. M — середина BC. Угол BAM = 23°. Найди BAC.", 46, "Докажи равенство ABM и ACM по трём сторонам.", ["AB = AC, BM = CM, AM — общая.", "Треугольники равны, значит BAM = MAC.", "BAC = 23° + 23° = 46°."]]], "check": "Две равные стороны равнобедренного треугольника по 6, основание 4. Периметр?", "answer": 16}, {"grade": 7, "subject": "geometry", "name": "Неравенство треугольника", "kind": "triangle", "intro": "Сумма любых двух сторон треугольника строго больше третьей. Это условие отличает настоящий треугольник от трёх точек на одной прямой.", "rules": ["Для сторон a, b, c: |a − b| < c < a + b.", "Строгие границы исключаются.", "Напротив большей стороны лежит больший угол."], "problems": [["Верхняя граница", "Две стороны равны 4 и 7. Найди наибольшую возможную целую длину третьей.", 10, "Третья сторона строго меньше суммы.", ["3 < c < 11.", "Наибольшее целое значение 10."]], ["Все варианты", "Две стороны треугольника 5 и 8. Сколько целых значений может иметь третья сторона?", 9, "Выпиши целые числа между разностью и суммой.", ["3 < c < 13.", "Это числа от 4 до 12 включительно.", "Их 12 − 4 + 1 = 9."]], ["Равнобедренный выбор", "Периметр равнобедренного треугольника 17. Все стороны целые. Сколько различных длин может иметь основание?", 4, "Обозначь боковую сторону a, основание 17 − 2a.", ["Из 0 < 17 − 2a < 2a следует 17/4 < a < 17/2.", "Возможны a = 5, 6, 7, 8.", "Основания 7, 5, 3, 1 — четыре варианта."]]], "check": "Стороны 3 и 5: наименьшая целая третья сторона?", "answer": 3}, {"grade": 8, "subject": "geometry", "name": "Четырёхугольники", "kind": "quad", "intro": "Параллелограмм имеет попарно параллельные противоположные стороны. Прямоугольник, ромб и квадрат — его частные случаи с дополнительными свойствами.", "rules": ["Соседние углы параллелограмма дают 180°.", "Диагонали параллелограмма делятся точкой пересечения пополам.", "В ромбе диагонали перпендикулярны, в прямоугольнике равны."], "problems": [["Соседний угол", "Угол параллелограмма равен 68°. Найди соседний.", 112, "Соседние углы в сумме 180°.", ["180 − 68 = 112°."]], ["Диагональ", "Диагонали прямоугольника пересекаются в O. От вершины A до O — 6 см. Найди вторую диагональ.", 12, "Диагонали равны и делятся пополам.", ["AC = 2AO = 12 см.", "Вторая диагональ BD = AC = 12 см."]], ["Ромб", "Диагонали ромба равны 10 и 24 см. Найди его периметр.", 52, "Полудиагонали образуют прямоугольный треугольник.", ["Катеты равны 5 и 12.", "Сторона ромба √(25 + 144) = 13.", "Периметр 4 × 13 = 52 см."]]], "check": "Угол параллелограмма 70°. Противоположный угол?", "answer": 70}, {"grade": 8, "subject": "geometry", "name": "Площади многоугольников", "kind": "quad", "intro": "Площадь можно вычислять через основание и перпендикулярную высоту. Разбиение фигуры на треугольники позволяет выводить и проверять формулы.", "rules": ["S треугольника = ah/2.", "S параллелограмма = ah.", "S трапеции = (a + b)h/2."], "problems": [["Треугольник", "Основание треугольника 12, высота к нему 5. Найди площадь.", 30, "Нужна половина произведения.", ["S = 12 × 5 / 2 = 30."]], ["Трапеция", "Площадь трапеции 60, основания 8 и 12. Найди высоту.", 6, "Подставь данные в формулу площади.", ["60 = (8 + 12)h/2 = 10h.", "h = 6."]], ["Медиана и площадь", "Площадь ABC равна 48. M — середина BC, N — середина AM. Найди площадь BNC.", 24, "У треугольников ABC и BNC общее основание BC.", ["Высота из N к BC вдвое меньше высоты из A.", "При общем основании площадь уменьшается вдвое.", "S(BNC) = 48/2 = 24."]]], "check": "Основание параллелограмма 7, высота 4. Площадь?", "answer": 28}, {"grade": 8, "subject": "geometry", "name": "Окружность: касательные и хорды", "kind": "circle", "intro": "Касательная имеет с окружностью ровно одну общую точку. Радиус к этой точке перпендикулярен касательной. Равные расстояния от центра помогают сравнивать хорды.", "rules": ["Радиус к точке касания образует угол 90° с касательной.", "Отрезки касательных из одной точки равны.", "Перпендикуляр из центра к хорде делит хорду пополам."], "problems": [["Угол касания", "Найди угол между касательной и радиусом в точке касания.", 90, "Вспомни свойство касательной.", ["Радиус перпендикулярен касательной.", "Угол равен 90°."]], ["Длина касательной", "Расстояние от точки P до центра O равно 13, радиус 5. Найди длину касательной PT.", 12, "Треугольник OTP прямоугольный.", ["PT² = OP² − OT² = 169 − 25 = 144.", "PT = 12."]], ["Длина хорды", "Радиус окружности 13. Расстояние от центра до хорды 5. Найди хорду.", 24, "Половина хорды — катет прямоугольного треугольника.", ["Полухорда √(13² − 5²) = 12.", "Вся хорда равна 24."]]], "check": "Две касательные из P имеют длины PA = 9 и PB. Найди PB.", "answer": 9}, {"grade": 9, "subject": "geometry", "name": "Тригонометрия треугольника", "kind": "triangle", "intro": "Синус, косинус и тангенс острого угла задаются отношениями сторон прямоугольного треугольника. Теоремы синусов и косинусов расширяют вычисления на произвольные треугольники.", "rules": ["sin α = противолежащий катет / гипотенуза.", "c² = a² + b² − 2ab cos γ.", "S = ab sin γ / 2; γ — угол между a и b."], "problems": [["Синус угла", "Противолежащий катет 3, гипотенуза 5. Найди синус угла.", 0.6, "Раздели противолежащий катет на гипотенузу.", ["sin α = 3/5 = 0,6."]], ["Косинусы", "Две стороны равны 5 и 8, косинус угла между ними 1/2. Найди третью сторону.", 7, "Используй теорему косинусов.", ["c² = 25 + 64 − 2 × 5 × 8 × 1/2 = 49.", "c = 7."]], ["Две возможности", "Две стороны равны 6 и 10. Площадь треугольника 15. Найди сумму двух возможных углов между этими сторонами в градусах.", 180, "Синус угла равен 2S/(ab).", ["sin γ = 30/60 = 1/2.", "Угол может быть 30° или 150°.", "Их сумма 180°."]]], "check": "Катет 8, прилежащий к углу катет 6. Найди тангенс угла напротив катета 8.", "answer": 1.3333333333333333}, {"grade": 9, "subject": "geometry", "name": "Центральные и вписанные углы", "kind": "circle", "intro": "Центральный угол имеет вершину в центре окружности. Вписанный — на окружности. Если они опираются на одну дугу, вписанный вдвое меньше центрального.", "rules": ["Вписанный угол равен половине градусной меры его дуги.", "Вписанный угол, опирающийся на диаметр, прямой.", "Противоположные углы вписанного четырёхугольника дают 180°."], "problems": [["Половина дуги", "Вписанный угол опирается на дугу 86°. Найди угол.", 43, "Раздели меру дуги пополам.", ["86/2 = 43°."]], ["Вписанный четырёхугольник", "Угол A вписанного четырёхугольника ABCD равен 112°. Найди C.", 68, "A и C — противоположные.", ["A + C = 180°.", "C = 180 − 112 = 68°."]], ["Диаметр", "AB — диаметр длиной 10. Точка C лежит на окружности, AC = 6. Найди площадь ABC.", 24, "Угол ACB прямой.", ["BC = √(100 − 36) = 8.", "S = AC × BC / 2 = 6 × 8 / 2 = 24."]]], "check": "Центральный угол 124°, вписанный опирается на ту же дугу. Найди вписанный.", "answer": 62}, {"grade": 9, "subject": "geometry", "name": "Правильные многоугольники", "kind": "polygon", "intro": "У правильного многоугольника все стороны и углы равны. Соединив центр с вершинами, получаем равные равнобедренные треугольники.", "rules": ["Сумма внутренних углов n-угольника равна 180°(n − 2).", "Каждый внутренний угол правильного n-угольника равен 180° − 360°/n.", "В правильном шестиугольнике сторона равна радиусу описанной окружности."], "problems": [["Шестиугольник", "Найди внутренний угол правильного шестиугольника.", 120, "Подставь n = 6.", ["180 − 360/6 = 120°."]], ["Число сторон", "Внутренний угол правильного многоугольника равен 150°. Сколько у него сторон?", 12, "Внешний угол равен 30°.", ["360/n = 180 − 150 = 30.", "n = 12."]], ["Вписанный квадрат", "Квадрат вписан в окружность радиуса 5. Найди его площадь.", 50, "Диагональ квадрата — диаметр.", ["Диагональ d = 10.", "Для квадрата d² = 2a², значит S = a² = 100/2 = 50."]]], "check": "Сумма внутренних углов пятиугольника?", "answer": 540}, {"grade": 10, "subject": "geometry", "name": "Прямые и плоскости", "kind": "box", "intro": "В пространстве прямые могут быть не только параллельными или пересекающимися, но и скрещивающимися: тогда они не лежат в одной плоскости. Перпендикулярность плоскости требует более сильного условия, чем перпендикулярность одной прямой.", "rules": ["Через три неколлинеарные точки проходит единственная плоскость.", "Прямая перпендикулярна плоскости, если перпендикулярна двум пересекающимся прямым этой плоскости.", "Угол между прямой и плоскостью — угол между прямой и её ортогональной проекцией."], "problems": [["Перпендикуляр", "Прямая перпендикулярна плоскости. Найди угол между ними.", 90, "Перпендикуляр образует прямой угол с плоскостью.", ["По определению угол равен 90°."]], ["Наклонная", "Наклонная к плоскости имеет длину 10, её проекция — 8. Найди расстояние от начала наклонной до плоскости.", 6, "Проекция и перпендикуляр образуют катеты.", ["h² = 10² − 8² = 36.", "h = 6."]], ["Две наклонные", "Из точки к плоскости проведены наклонные 13 и 15. Проекция первой равна 5. Найди проекцию второй.", 9, "Перпендикуляр к плоскости общий для обеих наклонных.", ["h² = 13² − 5² = 144.", "Вторая проекция имеет квадрат 15² − 144 = 81.", "Её длина 9."]]], "check": "Наклонная 5, перпендикуляр 3. Найди проекцию.", "answer": 4}, {"grade": 10, "subject": "geometry", "name": "Пирамида и сечения", "kind": "pyramid", "intro": "У пирамиды есть многоугольное основание и общая вершина боковых граней. Высота перпендикулярна плоскости основания. Параллельное основанию сечение подобно основанию.", "rules": ["V = S основания × h / 3.", "Линейные размеры сечения пропорциональны расстоянию от вершины.", "У подобных пирамид объёмы относятся как куб коэффициента подобия."], "problems": [["Объём пирамиды", "Площадь основания 30, высота 9. Найди объём.", 90, "Раздели произведение площади на высоту на 3.", ["V = 30 × 9 / 3 = 90."]], ["Сечение на половине", "Пирамида объёмом 64 рассечена плоскостью через середину высоты параллельно основанию. Найди объём меньшей пирамиды.", 8, "Коэффициент подобия 1/2.", ["Отношение объёмов равно (1/2)³ = 1/8.", "Меньший объём 64/8 = 8."]], ["Усечённая часть", "Сечение параллельно основанию проходит на расстоянии 2 от вершины пирамиды высотой 6. Полный объём 81. Найди объём части между сечением и основанием.", 78, "Вычти объём маленькой пирамиды.", ["Коэффициент подобия 2/6 = 1/3.", "Маленький объём 81/27 = 3.", "Остальная часть 81 − 3 = 78."]]], "check": "Площадь основания 12, высота 6. Объём?", "answer": 24}, {"grade": 10, "subject": "geometry", "name": "Призмы и пространственная диагональ", "kind": "box", "intro": "Призма имеет два равных параллельных основания. В прямой призме боковые рёбра перпендикулярны основаниям. Пространственную диагональ находят, последовательно применяя теорему Пифагора.", "rules": ["Объём любой призмы V = S основания × h.", "У прямой призмы площадь боковой поверхности равна периметру основания, умноженному на высоту.", "У прямоугольного параллелепипеда d² = a² + b² + c²."], "problems": [["Диагональ коробки", "Рёбра прямоугольного параллелепипеда равны 2, 3 и 6. Найди диагональ.", 7, "Сложи квадраты трёх рёбер.", ["d² = 4 + 9 + 36 = 49.", "d = 7."]], ["Поверхность призмы", "Основание прямой призмы — треугольник со сторонами 3, 4, 5. Высота призмы 10. Найди полную площадь поверхности.", 132, "Основание — прямоугольный треугольник.", ["Площадь основания 3 × 4/2 = 6.", "Боковая поверхность (3 + 4 + 5) × 10 = 120.", "Полная: 120 + 2 × 6 = 132."]], ["Угол диагонали", "У куба ребро 4. Найди квадрат синуса угла пространственной диагонали с плоскостью основания.", 0.3333333333333333, "Перпендикулярная составляющая диагонали равна ребру куба.", ["Длина диагонали 4√3.", "sin α = 4/(4√3) = 1/√3.", "sin² α = 1/3."]]], "check": "Периметр основания прямой призмы 14, высота 5. Боковая поверхность?", "answer": 70}, {"grade": 11, "subject": "geometry", "name": "Цилиндр", "kind": "cylinder", "intro": "Цилиндр получается вращением прямоугольника вокруг стороны. Его боковая поверхность разворачивается в прямоугольник шириной 2πr и высотой h.", "rules": ["V = πr²h.", "S боковой = 2πrh.", "S полной = 2πrh + 2πr²."], "problems": [["Объём", "Радиус цилиндра 3, высота 5. Найди V/π.", 45, "Вычисли r²h.", ["V = π × 9 × 5 = 45π.", "V/π = 45."]], ["Полная поверхность", "Радиус 2, высота 7. Найди полную площадь поверхности, разделённую на π.", 36, "Сложи боковую поверхность и два основания.", ["S/π = 2 × 2 × 7 + 2 × 2².", "28 + 8 = 36."]], ["Осевое сечение", "Осевое сечение цилиндра — квадрат площадью 64. Найди V/π.", 128, "Сторона квадрата одновременно высота и диаметр.", ["Высота и диаметр равны 8, радиус 4.", "V/π = 4² × 8 = 128."]]], "check": "Радиус 2, высота 3. Найди V/π.", "answer": 12}, {"grade": 11, "subject": "geometry", "name": "Конус", "kind": "cone", "intro": "Конус имеет круговое основание и вершину. Радиус, высота и образующая прямого кругового конуса составляют прямоугольный треугольник.", "rules": ["l² = r² + h².", "V = πr²h/3.", "S боковой = πrl; полная площадь дополнительно включает πr²."], "problems": [["Образующая", "Радиус конуса 3, высота 4. Найди образующую.", 5, "Примени теорему Пифагора.", ["l = √(9 + 16) = 5."]], ["Поверхность", "Радиус 5, образующая 13. Найди полную площадь поверхности конуса, разделённую на π.", 90, "Полная поверхность включает основание.", ["S/π = rl + r² = 5 × 13 + 25.", "Ответ: 90."]], ["Подобный конус", "Объём конуса 216. Параллельное основанию сечение делит высоту в отношении 1 : 2, считая от вершины. Найди объём отсечённого малого конуса.", 8, "Высота малого конуса равна трети полной.", ["Коэффициент подобия 1/(1 + 2) = 1/3.", "Объём уменьшается в 27 раз.", "216/27 = 8."]]], "check": "Радиус 3, высота 6. Найди V/π.", "answer": 18}, {"grade": 11, "subject": "geometry", "name": "Сфера и шар", "kind": "sphere", "intro": "Сфера — поверхность, шар — тело внутри неё. Плоское сечение шара является кругом; его радиус связан с расстоянием от плоскости до центра.", "rules": ["S сферы = 4πR².", "V шара = 4πR³/3.", "Для сечения r² = R² − d², где d — расстояние от центра до плоскости."], "problems": [["Площадь сферы", "Радиус сферы 3. Найди площадь поверхности, разделённую на π.", 36, "Вычисли 4R².", ["S/π = 4 × 9 = 36."]], ["Сечение шара", "Радиус шара 13. Плоскость находится на расстоянии 5 от центра. Найди радиус сечения.", 12, "Используй прямоугольный треугольник.", ["r² = 13² − 5² = 144.", "r = 12."]], ["Переплавка", "Шар радиуса 6 переплавили без потерь в одинаковые шарики радиуса 2. Сколько шариков получилось?", 27, "Отношение объёмов равно кубу отношения радиусов.", ["Число шариков (6/2)³ = 3³.", "Получается 27 шариков."]]], "check": "Радиус шара удвоили. Во сколько раз увеличился объём?", "answer": 8}, {"grade": 7, "subject": "algebra", "name": "Многочлены и разложение на множители", "kind": "", "intro": "Многочлен — сумма одночленов. Общий множитель и формулы сокращённого умножения помогают переходить от суммы к произведению.", "rules": ["Приводи подобные слагаемые.", "ab + ac = a(b + c).", "a² − b² = (a − b)(a + b)."], "problems": [["Подобные слагаемые", "Вычисли 3x + 5x − 2 при x = 4.", 30, "Сначала объедини слагаемые с x.", ["8x − 2 = 32 − 2 = 30."]], ["Разность квадратов", "Найди 51² − 49².", 200, "Используй произведение суммы и разности.", ["(51 − 49)(51 + 49) = 2 × 100 = 200."]], ["Произведение", "Известно a + b = 12 и a² + b² = 80. Найди ab.", 32, "Раскрой квадрат суммы.", ["144 = 80 + 2ab.", "2ab = 64, ab = 32."]]], "check": "Вычисли 2x + 3x при x = 2.", "answer": 10}, {"grade": 7, "subject": "algebra", "name": "Степень с натуральным показателем", "kind": "", "intro": "Показатель степени считает число одинаковых множителей. Правила работают с одинаковыми основаниями; знак зависит от скобок.", "rules": ["aᵐaⁿ = aᵐ⁺ⁿ.", "(aᵐ)ⁿ = aᵐⁿ.", "При чётном показателе отрицательное основание даёт положительное значение."], "problems": [["Чётная степень", "Вычисли (−3)⁴.", 81, "Умножь четыре отрицательных тройки.", ["(−3)² = 9, затем 9² = 81."]], ["Частное степеней", "Вычисли 2⁹ / 2⁶.", 8, "Вычти показатели.", ["2⁹ / 2⁶ = 2³ = 8."]], ["Последняя цифра", "Найди последнюю цифру 3²⁰.", 1, "Последние цифры повторяются через четыре степени.", ["Цикл: 3, 9, 7, 1.", "20 делится на 4, последняя цифра 1."]]], "check": "Вычисли 5³.", "answer": 125}, {"grade": 8, "subject": "algebra", "name": "Квадратные неравенства: первые шаги", "kind": "", "intro": "Знак произведения зависит от знаков множителей. Нули множителей делят числовую прямую на интервалы постоянного знака.", "rules": ["Найди корни.", "Проверь знак на каждом интервале.", "Строгие неравенства исключают корни."], "problems": [["Квадрат", "Найди наибольшее целое решение x² < 9.", 2, "Число должно лежать строго между −3 и 3.", ["−3 < x < 3, наибольшее целое 2."]], ["Произведение", "Сколько целых решений у (x − 1)(x − 5) ≤ 0?", 5, "Произведение неположительно между корнями.", ["1 ≤ x ≤ 5.", "Целых чисел 5."]], ["Два условия", "Сколько целых x одновременно удовлетворяют x² ≤ 16 и x > −2?", 6, "Пересечи интервалы.", ["−4 ≤ x ≤ 4 и x > −2.", "Целые −1, 0, 1, 2, 3, 4 — всего 6."]]], "check": "Наибольшее целое решение x² ≤ 25?", "answer": 5}, {"grade": 8, "subject": "algebra", "name": "Дробные уравнения", "kind": "", "intro": "После приведения к общему знаменателю уравнение часто становится линейным или квадратным. Исключённые знаменателем значения проверяют до и после преобразований.", "rules": ["Запиши ограничения знаменателей.", "Умножь на общий ненулевой знаменатель.", "Проверь корни в исходном уравнении."], "problems": [["Один знаменатель", "Реши 12/x = 3.", 4, "x не равен нулю.", ["12 = 3x, x = 4."]], ["Сдвиг", "Реши 5/(x − 2) = 1.", 7, "Исключи x = 2.", ["x − 2 = 5, x = 7."]], ["Работа вместе", "Один мастер делает работу за 6 часов, другой за 12. За сколько часов выполнят её вместе?", 4, "Сложи доли работы за час.", ["1/6 + 1/12 = 1/4 работы в час.", "Полная работа займёт 4 часа."]]], "check": "Реши 8/x = 2.", "answer": 4}, {"grade": 9, "subject": "algebra", "name": "Системы нелинейных уравнений", "kind": "", "intro": "Квадратичное условие вместе с линейным удобно решать подстановкой. Иногда достаточно найти симметричное выражение без вычисления каждого неизвестного.", "rules": ["Вырази переменную из линейного уравнения.", "Реши полученное квадратное уравнение.", "Проверь каждую пару."], "problems": [["Сумма и произведение", "x + y = 7, xy = 12. Найди большее из чисел.", 4, "Ищи корни t² − 7t + 12.", ["Корни 3 и 4. Большее число 4."]], ["Квадраты", "x + y = 9, xy = 14. Найди x² + y².", 53, "Используй квадрат суммы.", ["x² + y² = 81 − 28 = 53."]], ["Разность", "x² + y² = 65, x − y = 3. Найди xy.", 28, "Раскрой квадрат разности.", ["9 = 65 − 2xy.", "xy = 28."]]], "check": "x + y = 6, xy = 8. Найди x² + y².", "answer": 20}, {"grade": 9, "subject": "algebra", "name": "Степени и корни", "kind": "", "intro": "Степени с целыми показателями расширяют привычные правила. Отрицательный показатель означает обратное число, а не отрицательный результат.", "rules": ["a⁰ = 1 при a ≠ 0.", "a⁻ⁿ = 1/aⁿ при a ≠ 0.", "Для арифметических корней учитывай область определения."], "problems": [["Отрицательный показатель", "Вычисли 2⁻³.", 0.125, "Возьми обратное к 2³.", ["2⁻³ = 1/8 = 0,125."]], ["Смешанные степени", "Вычисли 3⁴ × 3⁻².", 9, "Сложи показатели.", ["3⁴⁻² = 3² = 9."]], ["Корни", "Вычисли (√5 + 2)(√5 − 2).", 1, "Разность квадратов.", ["5 − 4 = 1."]]], "check": "Вычисли 10⁻².", "answer": 0.01}, {"grade": 10, "subject": "algebra", "name": "Преобразования тригонометрических выражений", "kind": "", "intro": "Тождества позволяют преобразовать выражение, сохраняя его значение при допустимых аргументах. Выбор формулы зависит от того, какие величины уже известны.", "rules": ["sin² x + cos² x = 1.", "cos 2x = 1 − 2sin² x.", "sin 2x = 2sin x cos x."], "problems": [["Основное тождество", "Вычисли 1 − sin² 30°.", 0.75, "Синус 30° равен 1/2.", ["1 − 1/4 = 3/4."]], ["Двойной угол", "sin α = 3/5. Найди cos 2α.", 0.28, "Используй 1 − 2sin² α.", ["1 − 18/25 = 7/25 = 0,28."]], ["Сумма", "sin α + cos α = 1. Найди sin 2α.", 0, "Возведи равенство в квадрат.", ["1 + sin 2α = 1.", "sin 2α = 0."]]], "check": "Найди cos 60°.", "answer": 0.5}, {"grade": 10, "subject": "algebra", "name": "Логарифмические уравнения", "kind": "", "intro": "Логарифмическое уравнение имеет смысл только при положительных аргументах и допустимом основании. Сначала область определения, затем преобразования.", "rules": ["Основание a > 0, a ≠ 1.", "Аргумент логарифма положителен.", "logₐ x = b равносильно x = aᵇ."], "problems": [["По определению", "Реши log₃ x = 2.", 9, "Возведи 3 в квадрат.", ["x = 3² = 9."]], ["Аргумент со сдвигом", "Реши log₂(x − 3) = 4.", 19, "x > 3.", ["x − 3 = 16.", "x = 19 допустимо."]], ["Два логарифма", "Реши log₂ x + log₂(x − 2) = 3.", 4, "x > 2; объедини логарифмы.", ["x(x − 2) = 8.", "x² − 2x − 8 = 0, корни 4 и −2.", "Подходит только 4."]]], "check": "Реши log₅ x = 1.", "answer": 5}, {"grade": 11, "subject": "algebra", "name": "Исследование функции", "kind": "", "intro": "Производная помогает найти интервалы монотонности, экстремумы и оптимальные значения. На отрезке важно сравнить критические точки с концами.", "rules": ["Найди область определения.", "Исследуй знак производной.", "Для наибольшего значения на отрезке проверь также границы."], "problems": [["Критическая точка", "Найди точку минимума x² − 10x + 1.", 5, "Приравняй производную нулю.", ["2x − 10 = 0, x = 5.", "Производная меняет знак с минуса на плюс."]], ["Максимум на отрезке", "Найди максимум x² на [−3; 2].", 9, "Сравни значения на границах и в нуле.", ["Значения: 9, 4 и 0.", "Максимум 9."]], ["Оптимальная площадь", "Площадь прямоугольника с периметром 24 должна быть максимальна. Найди её.", 36, "Стороны x и 12 − x.", ["S = x(12 − x) = 36 − (x − 6)².", "Максимум 36."]]], "check": "Точка минимума (x − 2)²?", "answer": 2}, {"grade": 11, "subject": "algebra", "name": "Первообразная и накопление", "kind": "", "intro": "Неопределённый интеграл задаёт семейство первообразных. Начальное условие определяет константу. Определённый интеграл вычисляет накопленное изменение.", "rules": ["Все первообразные отличаются константой C.", "Проверяй ответ дифференцированием.", "При известной скорости перемещение равно интегралу скорости по времени."], "problems": [["Значение первообразной", "F′(x) = 2x, F(0) = 3. Найди F(2).", 7, "F = x² + C.", ["Из F(0) = 3 следует C = 3.", "F(2) = 4 + 3 = 7."]], ["Перемещение", "Скорость v(t) = 2t м/с. Найди путь за время от t = 0 до t = 4 с.", 16, "На этом промежутке скорость неотрицательна.", ["Интеграл 2t равен t².", "Путь 4² − 0² = 16 м."]], ["Константа", "F′(x) = 3x² − 2, F(1) = 4. Найди F(2).", 9, "Сначала найди C.", ["F = x³ − 2x + C.", "1 − 2 + C = 4, значит C = 5.", "F(2) = 8 − 4 + 5 = 9."]]], "check": "F′ = 1, F(0) = 2. Найди F(3).", "answer": 5}];

for(const item of deeperTopics){if(item.name==='Квадратные неравенства: первые шаги')item.grade=9;}
const supportedGrades=[6,7,8,9,10,11];
for(const g of Object.keys(curriculum))if(+g<6)delete curriculum[g];
for(const key of Object.keys(lessons))if(+key.split('-')[0]<6)delete lessons[key];
for(let i=tasks.length-1;i>=0;i--)if(tasks[i].grade<6)tasks.splice(i,1);
const geometryIndices={7:[2],8:[2],9:[3],10:[2,4],11:[]};
const topicSubjects={};
for(const g of supportedGrades)curriculum[g].forEach((t,i)=>topicSubjects[`${g}-${i}`]=g===6?'math':geometryIndices[g].includes(i)?'geometry':'algebra');
for(const item of deeperTopics){const {grade,subject,name,kind,intro,rules,problems,check,answer}=item;const topic=curriculum[grade].length;const key=`${grade}-${topic}`;curriculum[grade].push([name,intro.split('.')[0],subject==='geometry'?'△':subject==='math'?'π':'ƒ',[]]);topicSubjects[key]=subject;const example=problems[0];lessons[key]=L(intro,rules,example[1],example[4],'Сначала выпиши условия применяемой формулы. Рисунок помогает рассуждать, но измерять ответ по нему нельзя.',check,answer);lessons[key].diagram=kind;problems.forEach((p,level)=>{const [title,question,answer,hint,steps]=p;tasks.push({id:`${grade}-${topic}-${level}-rf1`,grade,topic,topicName:name,subject,level,title,question,answer,hint,hints:[hint],steps,solution:steps.join(' '),isNew:true,goal:['Освоить свойство','Связать несколько фактов','Построить рассуждение'][level]})})}
for(const t of tasks)t.subject=topicSubjects[`${t.grade}-${t.topic}`];
for(const [key,subject] of Object.entries(topicSubjects)){if(subject==='geometry'&&!lessons[key].diagram)lessons[key].diagram=key.startsWith('10-')?'box':'triangle';}
